    for (let i = 1; i < data.length; i++) {
      const storedUser = String(data[i][1]).toLowerCase().trim();
      if (storedUser === username) {
        const storedPass = String(data[i][2] || "").trim();
        const isEnabled = data[i][8] === undefined || data[i][8] === "" || String(data[i][8]).toUpperCase() === "TRUE";
        let prefs = {};
        try { if (data[i][7]) prefs = JSON.parse(data[i][7]); } catch(e) {}
        if (isEnabled && prefs.passwordCleared === true && storedPass === "") {
          return ResponseBuilder.success({
            eligible: true,
            user: {
              id: data[i][0],
              username: storedUser,
              name: String(data[i][3] || ""),
              role: String(data[i][4] || "Inspector").trim(),
              position: data[i][5] || '',
              passwordCleared: true,
              preferences: prefs,
              isActive: true
            }
          });
        }
        return ResponseBuilder.success({ eligible: false });
      }
    }
    return ResponseBuilder.success({ eligible: false });
